import type { PayrollCode } from './driverPayrollTypes';

const normalizePayrollName = (value: string): string => {
  return value
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
};

const code = (item: Omit<PayrollCode, 'normalizedName'>): PayrollCode => ({
  ...item,
  normalizedName: normalizePayrollName(item.label),
});

