export function findDefaultPayrollCode(value: string): PayrollCode | undefined {
  const normalized = normalizePayrollName(value);

  return DEFAULT_PAYROLL_CODES.find((item) => {
    if (item.code === value.trim()) return true;
    if (item.normalizedName === normalized) return true;
    return item.parserAliases.some((alias) => normalizePayrollName(alias) === normalized);
  });
}
